package cn.quit5700.buildingwand.aux;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.SharedConstants;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeAll;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
class AuxRowTest {
 @BeforeAll static void version(){SharedConstants.tryDetectVersion();}
 private static AuxRow row(int shape,boolean solid){var n=AuxRow.create(new BlockPos(2,3,4),new BlockPos(8,9,10));n.putInt("Shape",shape);n.putBoolean("Solid",solid);return new AuxRow(n);}
 @Test void allTwelveShapesAreNonemptyBoundedAndHollowIsASubset(){for(int shape=0;shape<12;shape++){var solid=row(shape,true);var hollow=row(shape,false);long count=0;for(int x=-1;x<=7;x++)for(int y=-1;y<=7;y++)for(int z=-1;z<=7;z++){boolean a=solid.contains(x,y,z),b=hollow.contains(x,y,z);if(a){count++;assertTrue(x>=0&&x<7&&y>=0&&y<7&&z>=0&&z<7);}if(b)assertTrue(a);}assertTrue(count>0,"Empty shape "+shape);}}
 @Test void cuboidReallyContainsEveryCellAndHollowPreservesInterior(){var solid=row(0,true);var hollow=row(0,false);assertTrue(solid.contains(3,3,3));assertFalse(hollow.contains(3,3,3));assertTrue(hollow.contains(0,3,3));}
 @Test void planarShapesUseFirstHeightEvenWhenSecondPointIsLower(){for(int shape:new int[]{4,5,7,9,11}){var n=AuxRow.create(new BlockPos(0,9,0),new BlockPos(6,3,6));n.putInt("Shape",shape);var r=new AuxRow(n);for(int x=0;x<7;x++)for(int y=0;y<7;y++)for(int z=0;z<7;z++)if(r.contains(x,y,z))assertEquals(9,r.world(x,y,z).getY());}}
 @Test void pyramidPointOrderFlipsItsTip(){var up=row(3,true);var tag=up.data.copy();tag.putBoolean("Down",true);var down=new AuxRow(tag);for(int x=0;x<7;x++)for(int y=0;y<7;y++)for(int z=0;z<7;z++)assertEquals(up.contains(x,y,z),down.contains(x,6-y,z));}
 @Test void fourQuarterTurnsPreservePositionsAndMicroEditsOnEveryAxis(){for(int axis=0;axis<3;axis++){var r=row(0,true);var erased=r.world(1,2,3);r.remove(erased);var before=r.data.copy();for(int i=0;i<4;i++)r.rotate(axis,new BlockPos(-20,7,14),1);assertEquals(new AuxRow(before).world(5,2,1),r.world(5,2,1));int[] local=r.local(erased);assertFalse(r.contains(local[0],local[1],local[2]));assertArrayEquals(cn.quit5700.buildingwand.aux.LegacyNbt.longArray(before,"Removed").orElseThrow(),cn.quit5700.buildingwand.aux.LegacyNbt.longArray(r.data,"Removed").orElseThrow());}}
 @Test void worldLocalMappingIsReversibleAfterGroupMovement(){var r=row(1,true);r.rotate(0,new BlockPos(1,2,3),3);r.rotate(2,new BlockPos(2,0,4),1);r.translate(21,-7,-19);for(int x=0;x<7;x++)for(int y=0;y<7;y++)for(int z=0;z<7;z++)assertArrayEquals(new int[]{x,y,z},r.local(r.world(x,y,z)));}
 @Test void copyOnWriteMicroDeletionDoesNotAlterAnotherRow(){var r=row(0,true);var copy=r.copy();copy.remove(copy.world(2,2,2));assertTrue(r.contains(2,2,2));assertFalse(copy.contains(2,2,2));copy.translate(20,0,0);assertEquals(2,r.world(0,0,0).getX());}
 @Test void tinyShapesStillHaveOneVoxelAndSphereKeepsItsDiameter(){for(int shape=0;shape<12;shape++){var n=AuxRow.create(BlockPos.ZERO,BlockPos.ZERO);n.putInt("Shape",shape);assertTrue(new AuxRow(n).contains(0,0,0),"Tiny shape "+shape);}var n=AuxRow.create(BlockPos.ZERO,new BlockPos(0,1,0));n.putInt("Shape",1);var r=new AuxRow(n);assertTrue(r.contains(0,0,0));assertFalse(r.contains(0,1,0));}
 @Test void nonSquarePyramidBaseStartsAtTheFirstCorner(){var n=AuxRow.create(BlockPos.ZERO,new BlockPos(9,4,4));n.putInt("Shape",3);var r=new AuxRow(n);assertTrue(r.contains(0,0,0));assertTrue(r.contains(4,0,4));assertFalse(r.contains(5,0,4));var reversed=AuxRow.create(new BlockPos(9,0,4),new BlockPos(0,4,0));reversed.putInt("Shape",3);assertTrue(new AuxRow(reversed).contains(9,0,4));}
 @Test void thinPlanesAndFittedSpheresDoNotScanTheirUnusedBoundingVolume(){var n=AuxRow.create(BlockPos.ZERO,new BlockPos(6,1000000,6));n.putInt("Shape",4);assertEquals(49,new AuxRow(n).volume());n.putInt("Shape",1);assertEquals(343,new AuxRow(n).volume());n.putInt("Shape",99);assertThrows(IllegalArgumentException.class,()->new AuxRow(n));}
 @Test void realCastleUsesSparseNonAirIterationAndCopiesDoNotLoseCells()throws Exception{CompoundTag source;try(var input=getClass().getResourceAsStream("/blueprints/q5_grand_castle.nbt")){source=cn.quit5700.buildingwand.blueprint.BlueprintReader.vanilla(NbtIo.readCompressed(input,NbtAccounter.create(512L*1024*1024)));}var n=AuxRow.blank();n.putInt("W",96);n.putInt("H",45);n.putInt("D",80);n.putBoolean("Placed",true);n.put("Blueprint",source);var row=new AuxRow(n);assertEquals(70870,row.volume());for(long i=0;i<row.volume();i++){var p=row.coordinates(i);assertTrue(row.contains(p[0],p[1],p[2]));}var copy=row.copy();copy.rotate(1,BlockPos.ZERO,1);copy.translate(100,0,0);assertEquals(row.volume(),copy.volume());int[] p=row.coordinates(0);copy.remove(copy.world(p[0],p[1],p[2]));assertTrue(row.contains(p[0],p[1],p[2]));assertFalse(copy.contains(p[0],p[1],p[2]));}
 @Test void savedRowsRetainVisibilityShapeMaterialAndRemovedCells()throws Exception{var r=row(9,false);r.data.putBoolean("Visible",false);r.data.putString("Material","minecraft:stone");r.remove(r.world(3,0,3));byte[] bytes=cn.quit5700.buildingwand.blueprint.BlueprintNbt.compress(r.data);var loaded=new AuxRow(NbtIo.readCompressed(new java.io.ByteArrayInputStream(bytes),NbtAccounter.create(1024*1024)));assertEquals(r.data,loaded.data);}
 @Test void scaledOrReflectedMatricesAreRejected(){for(int[] m:new int[][]{{2,0,0,0,1,0,0,0,1},{-1,0,0,0,1,0,0,0,1},{1,0,0,0,1,0,0,0,0}}){var r=row(0,true).data;r.putIntArray("Matrix",m);assertThrows(IllegalArgumentException.class,()->new AuxRow(r));}}
}
